"""Export a verified frozen prediction, explicitly distinct from reference FEM."""
import argparse,base64,gzip,hashlib,html,json,re,secrets,sys
from pathlib import Path
import numpy as np
REPO=Path(__file__).resolve().parents[1];sys.path.insert(0,str(REPO))
from solid.mesh import prepare_mesh,nodal_load

def main(args):
    digest=lambda b:hashlib.sha256(b).hexdigest();run=args.run;metrics=json.loads((run/'metrics.json').read_text());campaign=json.loads(args.campaign.read_text());assert metrics['kind']=='modal_energy' and not metrics['accepted_for_solver_routing'];assert digest((run/'best.pt').read_bytes())==metrics['checkpoint_sha256'];assert digest(args.campaign.read_bytes())==metrics['evaluation_campaign_sha256'];case=next(c for c in metrics['cases'] if c['case_id']==args.case and c['split']=='test');scene=next(c['scene'] for c in campaign['cases'] if c['case_id']==args.case);path=run/case['field_file'];assert path.resolve().is_relative_to(run.resolve()) and digest(path.read_bytes())==case['field_sha256']
    with np.load(path,allow_pickle=False) as data:
        parts=data['parts_m'];values=parts.sum(2) if args.part=='full' else parts[:,:,{'linear':0,'geometric':1,'material':2}[args.part]];values=np.ascontiguousarray(values,dtype='<f8');points=data['points_mm'];tetra=data['tetra'];surface=data['surface'];times=data['times_us']
    assert values.nbytes<=192*1024**2 and np.isfinite(values).all();raw=values.tobytes();packed=gzip.compress(raw,compresslevel=6,mtime=0);mesh=prepare_mesh(points*.001,tetra);_,loaded=nodal_load(mesh,scene['source']);guard=case['all_saved_frame_guard'];config=json.loads((run/'config.json').read_text())
    record={'schema':'workai.modal_prediction.result.v1','engine':'workai_modal_energy_3d','job_id':args.case+'-'+args.part,'response_part':args.part,'scene':scene,'accepted_for_solver_routing':False,'nodes_mm':points.tolist(),'tetra':tetra.tolist(),'surface':surface.tolist(),'times_us':times.tolist(),'loaded_faces':np.flatnonzero(loaded).tolist(),'evidence':{'run_id':run.name,'checkpoint_sha256':metrics['checkpoint_sha256'],'prediction_archive_sha256':case['field_sha256'],'transient_labels_used_for_prediction':False,'acceptance':metrics['acceptance']},'diagnostics':{'output_dtype':'float64','internal_step_us':config['step_us'],'external_work_balance_relative':None,'max_strain':guard['max_green_strain'],'min_J':guard['min_J']},'field':{'layout':'time,node,xyz','dtype':'little_endian_float64','unit':'m','shape':list(values.shape),'compressed_bytes':len(packed),'uncompressed_bytes':len(raw),'sha256':digest(packed),'uncompressed_sha256':digest(raw)}}
    source='\n'.join(re.sub(r'^export ','',re.sub(r'^import .*;\n','',(REPO/name).read_text(),flags=re.M),flags=re.M) for name in ['public/solid-data.js','public/modal-data.js','public/solid-viewer.js'])
    source+="\nconst record=JSON.parse(document.getElementById('modal-record').textContent);const packed=Uint8Array.from(atob(document.getElementById('modal-field').textContent.trim()),c=>c.charCodeAt(0));const container=document.getElementById('modal-view');try{const field=await decodeModalField(record,packed);container.innerHTML=solidResultMarkup(record);mountSolidResult(container,record,field);document.getElementById('modal-load').textContent='已核对预测场 SHA-256 · 浏览动画和提取点位不启动新求解';}catch(e){document.getElementById('modal-load').textContent=e.message;}"
    assert '</script' not in source.lower();nonce=secrets.token_hex(18);data=json.dumps(record,separators=(',',':'),ensure_ascii=False).replace('<','\\u003c');css=(REPO/'public/styles.css').read_text();part={'full':'完整位移','linear':'线性位移','geometric':'几何非线性增量','material':'材料非线性增量'}[args.part]
    page=f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'none';script-src 'nonce-{nonce}';style-src 'unsafe-inline';img-src data: blob:;connect-src 'none';base-uri 'none';form-action 'none'"><title>workAI · 降阶预测 · {part}</title><style>{css}\nbody{{min-width:0}}main{{max-width:1400px;margin:auto}}.panel{{margin-bottom:20px}}.solid-layout{{grid-template-columns:minmax(0,1.2fr) minmax(0,1fr)}}@media(max-width:1000px){{.solid-layout{{grid-template-columns:1fr}}}}</style></head><body><main><div class="page-heading"><div><div class="eyebrow">WORKAI · EXPERIMENTAL HYBRID PREDICTION</div><h1>{part} · 三维预测动画</h1><p>任意实体内点位与方向 · 波形及频谱 · 不重新求解</p></div></div><p>{html.escape(args.case)} · {html.escape(run.name)}</p><p id="modal-load">正在核对预测场…</p><div id="modal-view"></div></main><script type="application/json" id="modal-record">{data}</script><script type="application/octet-stream" id="modal-field">{base64.b64encode(packed).decode()}</script><script type="module" nonce="{nonce}">{source}</script></body></html>'''
    with args.output.open('x') as f:f.write(page)
    print(json.dumps({'path':str(args.output),'bytes':args.output.stat().st_size,'sha256':digest(args.output.read_bytes()),'case_id':args.case,'part':args.part,'prediction_only':True}))

if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('--run',type=Path,required=True);p.add_argument('--campaign',type=Path,required=True);p.add_argument('--case',required=True);p.add_argument('--part',choices=['full','linear','geometric','material'],default='full');p.add_argument('--output',type=Path,required=True);main(p.parse_args())
